# ---------------------------------------------------------------------------
# Record spec model
# ---------------------------------------------------------------------------


@dataclass
class RecordSpec:
    seq: int
    scopus_id: str
    year: int
    cover_date: str
    doi: str | None
    subtype: str
    subtype_description: str
    aggregation_type: str
    edge: str | None = None
    _language: str = "English"
    _country_override: tuple[str, str, str, str] | None = None


def _make_scopus_id(seq: int, edge: str | None) -> str:
    """12-digit synthetic SCOPUS_ID, disjoint from any real cassette id.

    Edge-case records get a reserved, easily-greppable ``9000000000NN``
    block (README.md's location table is keyed on these); every other
    record uses the ``2050470NNNNN`` block.
    """
    if edge is not None:
        edge_index = sorted(EDGE_POSITIONS).index(seq) + 1
        return f"90000000{edge_index:04d}"
    return f"2050470{seq:05d}"


def _make_title(rng: Random, seq: int) -> str:
    adj = rng.choice(_TITLE_WORDS)
    noun = rng.choice(_TITLE_NOUNS)
    context = rng.choice(_TITLE_CONTEXTS)
    pattern = seq % 3
    if pattern == 0:
        return f"{adj} {noun} for {context}"
    if pattern == 1:
        return f"{noun}: A {adj} Approach for {context}"
    return f"Towards {adj} {noun} in {context}"


def _make_abstract(rng: Random, title_context: str) -> str:
    adj = rng.choice(_TITLE_WORDS).lower()
    task = rng.choice(_TITLE_NOUNS).lower()
    opener = rng.choice(_ABSTRACT_OPENERS).format(adj=adj, task=task, context=title_context.lower())
    middle = " ".join(rng.sample(_ABSTRACT_MIDDLES, 2))
    closer = rng.choice(_ABSTRACT_CLOSERS)
    return f"{opener} {middle} {closer}"


def _make_keywords(rng: Random, count: int) -> str:
    return " | ".join(sorted(rng.sample(_KEYWORD_PHRASES, count)))


def _make_author(rng: Random, position: int, affiliation_afids: list[str]) -> dict[str, Any]:
    surname = rng.choice(_SURNAMES)
    given = rng.choice(_GIVEN_NAMES)
    initials = f"{given[0]}."
    authid = f"5{position:010d}"
    orcid_parts = [str(rng.randint(1000, 9999)) for _ in range(4)]
    orcid = "-".join(orcid_parts)
    chosen_afid = rng.choice(affiliation_afids)
    return {
        "@_fa": "true",
        "@seq": str(position + 1),
        "author-url": f"https://api.elsevier.com/content/author/author_id/{authid}",
        "authid": authid,
        "orcid": orcid,
        "authname": f"{surname} {initials}",
        "surname": surname,
        "given-name": given,
        "initials": initials,
        "afid": [{"@_fa": "true", "$": chosen_afid}],
    }


def _make_affiliation(
    institution: tuple[str, str, str, str], *, scalar_afid: bool
) -> dict[str, Any]:
    afid, name, city, country = institution
    return {
        "@_fa": "true",
        "affiliation-url": f"https://api.elsevier.com/content/affiliation/affiliation_id/{afid}",
        "afid": afid if scalar_afid else [afid],
        "affilname": name,
        "affiliation-city": city,
        "affiliation-country": country,
    }


def _entry_links(scopus_id: str) -> list[dict[str, Any]]:
    base = f"https://api.elsevier.com/content/abstract/scopus_id/{scopus_id}"
    return [
        {"@_fa": "true", "@ref": "self", "@href": base},
        {"@_fa": "true", "@ref": "author-affiliation", "@href": f"{base}?field=author,affiliation"},
        {
            "@_fa": "true",
            "@ref": "scopus",
            "@href": f"https://www.scopus.com/inward/record.uri?partnerID=HzOxMe3b&scp={scopus_id}&origin=inward",
        },
        {
            "@_fa": "true",
            "@ref": "scopus-citedby",
            "@href": f"https://www.scopus.com/inward/citedby.uri?partnerID=HzOxMe3b&scp={scopus_id}&origin=inward",
        },
    ]


def build_specs() -> list[RecordSpec]:
    """Build the 120 :class:`RecordSpec` in sequence order (no randomness here)."""
    specs: list[RecordSpec] = []
    years = list(range(2016, 2026))  # cycled; EDGE_PARTIAL_YEAR overrides to 2026
    for seq in range(TOTAL_RECORDS):
        edge = EDGE_POSITIONS.get(seq)
        year = years[seq % len(years)]
        cover_date = f"{year}-{(seq % 12) + 1:02d}-01"
        doi = f"10.1109/tpami.{year}.{2_000_000 + seq:07d}"
        subtype, subtype_desc, aggregation = (
            ("ar", "Article", "Journal")
            if seq % 5 != 0
            else ("cp", "Conference Paper", "Conference Proceedings")
        )

        spec = RecordSpec(
            seq=seq,
            scopus_id=_make_scopus_id(seq, edge),
            year=year,
            cover_date=cover_date,
            doi=doi,
            subtype=subtype,
            subtype_description=subtype_desc,
            aggregation_type=aggregation,
            edge=edge,
        )

        if edge == "partial_year":
            spec.year = 2026
            spec.cover_date = "2026-01-05"
        elif edge in ("duplicate_doi_a", "duplicate_doi_b"):
            spec.doi = DUPLICATE_DOI_VALUE
        elif edge == "non_english":
            spec._language = "German"
        elif edge == "unmapped_country":
            spec._country_override = _UNMAPPED_INSTITUTION

        specs.append(spec)
    return specs


def render_entry(rng: Random, spec: RecordSpec) -> dict[str, Any]:
    """Render one :class:`RecordSpec` into a Scopus-shaped ``entry`` dict."""
    scopus_id = spec.scopus_id

    if spec.edge == "unmapped_country":
        institutions = [spec._country_override]
    elif spec.edge == "many_authors":
        institutions = [rng.choice(_INSTITUTIONS), rng.choice(_INSTITUTIONS)]
    else:
        institutions = rng.sample(_INSTITUTIONS, rng.choice([1, 1, 2]))

    affiliation_afids = [inst[0] for inst in institutions]
    affiliations = [
        _make_affiliation(inst, scalar_afid=(spec.edge == "scalar_afid")) for inst in institutions
    ]

    author_count = 45 if spec.edge == "many_authors" else rng.choice([2, 2, 3, 3, 4, 5, 6])
    authors = [_make_author(rng, position, affiliation_afids) for position in range(author_count)]

    if spec.edge == "non_english":
        title = (
            "Robuste Erkennung von Anomalien in Videoüberwachungssequenzen: "
            "Ein Vergleichender Ansatz"
        )
        abstract = (
            "In dieser Arbeit wird ein robustes Verfahren zur Erkennung von "
            "Anomalien in Videoüberwachungssequenzen vorgestellt. Das Modell "
            "kombiniert raeumlich-zeitliche Merkmale mit einem selbstueberwachten "
            "Lernverfahren, um normale von auffaelligen Ereignissen zu "
            "unterscheiden. Die Auswertung erfolgt auf mehreren oeffentlichen "
            "Datensaetzen aus dem Bereich der staedtischen Ueberwachung. Die "
            "Ergebnisse zeigen eine konsistente Verbesserung gegenueber "
            "bestehenden Verfahren."
        )
    else:
        title = _make_title(rng, spec.seq)
        abstract = _make_abstract(rng, title)

    entry: dict[str, Any] = {
        "@_fa": "true",
        "link": _entry_links(scopus_id),
        "prism:url": f"https://api.elsevier.com/content/abstract/scopus_id/{scopus_id}",
        "dc:identifier": f"SCOPUS_ID:{scopus_id}",
        "eid": f"2-s2.0-{scopus_id}",
        "dc:title": title,
        "dc:creator": f"{authors[0]['surname']} {authors[0]['initials']}",
        "prism:publicationName": f"{title.split(':')[0][:40]} Proceedings"
        if spec.aggregation_type == "Conference Proceedings"
        else "Journal of Spatiotemporal Pattern Analysis",
        "prism:issn": f"{10000000 + spec.seq:08d}",
        "prism:eIssn": f"{20000000 + spec.seq:08d}",
        "prism:volume": str(10 + (spec.seq % 40)),
        "prism:pageRange": f"{100 + spec.seq}-{120 + spec.seq}",
        "prism:coverDate": spec.cover_date,
        "prism:coverDisplayDate": str(spec.year),
        "citedby-count": str(rng.randint(0, 150)),
        "affiliation": affiliations,
        "prism:aggregationType": spec.aggregation_type,
        "subtype": spec.subtype,
        "subtypeDescription": spec.subtype_description,
        "author-count": {"@limit": "100", "$": str(author_count)},
        "author": authors,
        "source-id": f"{30000 + (spec.seq % 500)}",
        "openaccess": "1" if spec.seq % 4 == 0 else "0",
        "openaccessFlag": spec.seq % 4 == 0,
        "language": spec._language,
    }

    if spec.doi is not None:
        entry["prism:doi"] = spec.doi

    if spec.edge != "no_abstract":
        entry["dc:description"] = abstract

    if spec.edge != "zero_keywords":
        keyword_count = rng.choice([3, 3, 4, 4, 5])
        entry["authkeywords"] = _make_keywords(rng, keyword_count)

    return entry


# ---------------------------------------------------------------------------
# Pagination envelope
# ---------------------------------------------------------------------------


def _cursor_token(label: str) -> str:
    """A deterministic, opaque-looking base64 cursor token."""
    return base64.b64encode(f"prismabib-reference-fixture-cursor-{label}".encode()).decode()


def build_pages(entries: list[dict[str, Any]], *, query: str) -> list[dict[str, Any]]:
    chunks = [entries[i : i + PAGE_SIZE] for i in range(0, len(entries), PAGE_SIZE)]
    tokens = [_cursor_token(str(i)) for i in range(1, len(chunks))]
    # Termination: the last page's @next equals its own @current (see
    # prismabib.sources.scopus.ScopusClient.search's termination check).
    currents = ["*", *tokens]
    nexts = [*tokens, tokens[-1] if tokens else "*"]

    pages: list[dict[str, Any]] = []
    encoded_query = quote(query)
    for index, chunk in enumerate(chunks):
        current = currents[index]
        nxt = nexts[index]
        link = [
            {
                "@_fa": "true",
                "@ref": "self",
                "@href": (
                    f"https://api.elsevier.com/content/search/scopus?cursor={quote(current)}"
                    f"&count=25&query={encoded_query}&view=COMPLETE"
                ),
                "@type": "application/json",
            },
            {
                "@_fa": "true",
                "@ref": "first",
                "@href": (
                    f"https://api.elsevier.com/content/search/scopus?cursor=*"
                    f"&count=25&query={encoded_query}&view=COMPLETE"
                ),
                "@type": "application/json",
            },
        ]
        if index < len(chunks) - 1:
            link.append(
                {
                    "@_fa": "true",
                    "@ref": "next",
                    "@href": (
                        f"https://api.elsevier.com/content/search/scopus?cursor={quote(nxt)}"
                        f"&count=25&query={encoded_query}&view=COMPLETE"
                    ),
                    "@type": "application/json",
                }
            )

        page = {
            "search-results": {
                "opensearch:totalResults": str(len(entries)),
                "opensearch:itemsPerPage": "25",
                "opensearch:Query": {
                    "@role": "request",
                    "@searchTerms": query,
                    "@startPage": "",
                },
                "cursor": {"@current": current, "@next": nxt},
                "link": link,
                "entry": chunk,
            }
        }
        pages.append(page)
    return pages


# ---------------------------------------------------------------------------
# Writing (mirrors src/prismabib/capture/writer.py's exact byte encoding)
# ---------------------------------------------------------------------------


# Deliberately no local encoder. Page files are written by
# `prismabib.capture.writer._write_page`, the exact function a real acquisition
# run uses, so this fixture cannot drift from production Layer 0. It drifted once
# already: the writer changed from "one page = one JSON line" to true JSON Lines
# (one record per line, envelope in a sibling `.meta.json`) and a hand-rolled copy
# here would have kept generating the old shape, testing a format the system no
# longer writes.


def main() -> None:
    rng = Random(SEED)

    specs = build_specs()
    entries = [render_entry(rng, spec) for spec in specs]

    project = Project(slug="reference", root=FIXTURE_ROOT)
    query = build_query_for_project(project)
    criteria_version = project.criteria.version

    pages = build_pages(entries, query=query)

    RUN_DIR.mkdir(parents=True, exist_ok=True)
    payload_files: list[str] = []
    for index, page in enumerate(pages):
        filename = f"page-{index:04d}.jsonl"
        _write_page(RUN_DIR, filename, page)
        payload_files.append(filename)

    digest = hashlib.sha256()
    for filename in payload_files:
        digest.update((RUN_DIR / filename).read_bytes())
    payload_sha256 = digest.hexdigest()

    manifest = RunManifest(
        run_id=RUN_ID,
        started_at=STARTED_AT,
        finished_at=FINISHED_AT,
        endpoint=ScopusClient.SEARCH_ENDPOINT,
        query=query,
        view="COMPLETE",
        total_results=TOTAL_RECORDS,
        pages_fetched=len(payload_files),
        payload_files=payload_files,
        payload_sha256=payload_sha256,
        client_version=CLIENT_VERSION,
        criteria_version=criteria_version,
    )
    # No trailing newline: mirrors capture/writer.py's _atomic_write_bytes call,
    # which writes exactly manifest.model_dump_json(indent=2).encode("utf-8") + b"\n".
    (RUN_DIR / "manifest.json").write_bytes(
        manifest.model_dump_json(indent=2).encode("utf-8") + b"\n"
    )

    print(f"Wrote {len(payload_files)} pages, {TOTAL_RECORDS} records, to {RUN_DIR}")
    print(f"payload_sha256={payload_sha256}")


if __name__ == "__main__":
    main()
